!function($){$(function(){$(document).ready(function(){if($('.btoc-container').hasClass('sticky-top')){$('.btoc-container').css('top',$('#topmenu').height()+10);$(window).resize(function(){$('.btoc-container').css('top',$('#topmenu').height()+10);});}
$('.btoc-nav').each(function(){var toc_levels=$(this).data('toc-levels');tocbot.init({tocElement:this,contentSelector:'section.body',headingSelector:toc_levels,collapseDepth:0,orderedList:false,hasInnerContainers:false,ignoreSelector:'.toc-skip',headingsOffset:0,scrollSmooth:false,scrollSmoothOffset:0,scrollSmoothDuration:420,throttleTimeout:50,});});$('a.toc-link').on('click',function(){$('a.toc-link').removeClass('clicked');$(this).addClass('clicked');});});})}(window.jQuery)